Object.assign(window.TEM8_DICTIONARY, {"offshore":{"media":{"uk":"media/uk/offshore__gb_1.mp3","us":"media/us/offshore__us_1.mp3"},"oxford":{"phon":"ˌɒfˈʃɔː(r)","pos":"adjective","senses":[{"en":"happening or existing in the sea, not far from the land","cn":"海上的；近海的","ex":{"en":"offshore drilling","cn":"近海钻探"}},{"en":"blowing from the land towards the sea","cn":"向海的；离岸的","ex":{"en":"offshore breezes","cn":"习习陆风"}},{"en":"kept or located in a foreign country that has more generous tax laws than the home country","cn":"离岸的（指设在税制较宽松的境外地区）","lab":"business","ex":{"en":"offshore investments","cn":"境外投资"}},{"en":"to arrange for people in another country to do work for it","cn":"安排另一个国家的人为其工作","ex":{"en":"Thousands of these jobs have been offshored.","cn":"数以千计的此类工作岗位已被外包。"},"pos":"verb"},{"en":"in the sea, not far from the land","cn":"在离陆地不远的海里","ex":{"en":"a ship anchored offshore","cn":"在近海停泊的船"},"pos":"adverb"},{"en":"if the wind is blowing offshore, it is blowing from the land towards the sea","cn":"从陆地吹向海洋","pos":"adverb"},{"en":"in a foreign country that has more generous tax laws than the home country","cn":"在一个税法比本国更宽松的外国","lab":"business","ex":{"en":"profits earned offshore","cn":"境外获取的利润"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"近岸的；近海的","en":"Offshore means situated or happening in the sea, near to the coast.","ex":{"en":"...Britain's offshore oil industry.","cn":"英国的近海石油工业"}},{"pos":"ADJ 形容词","cn":"（风）向海的，离岸的","en":"An offshore wind blows from the land towards the sea.","ex":{"en":"...a strong off-shore wind.","cn":"猛烈的离岸陆风"}},{"pos":"ADJ 形容词","cn":"（投资或公司）设在海外（尤指税制较宽松的岛屿）的,离岸的","en":"Offshore investments or companies are located in a place, usually an island, which has fewer tax regulations than most other countries.","ex":{"en":"The island offers a wide range of offshore banking facilities.","cn":"这座岛上有很多离岸金融机构。"}}]},"examples":[{"en":"a ship anchored offshore","cn":"一艘泊在海上的船"},{"en":"offshore drilling","cn":"近海钻探"}]},"oftentimes":{"media":{"uk":"media/uk/oftentimes__gb_1.mp3","us":"media/us/oftentimes__us_1.mp3"},"oxford":{"phon":"ˈɒfntaɪmz","pos":"adverb","senses":[{"en":"often","cn":"经常"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"常常；经常","en":"If something oftentimes happens, it happens many times or much of the time.","ex":{"en":"Oftentimes, these fossils are not made available to science at all","cn":"科学界常常压根接触不到这些化石。"}}]},"examples":[{"en":"Oftentimes I have to wait more than 20 minutes for a bus.","cn":"我经常得花二十多分钟才等到一辆公共汽车。"}]},"often":{"media":{"uk":"media/uk/often__gb_1.mp3","us":"media/us/often__us_1.mp3"},"oxford":{"phon":"ˈɒfn","pos":"adverb","senses":[{"en":"many times","cn":"时常；常常","ex":{"en":"We often go there.","cn":"我们常去那里。"}},{"en":"in many cases","cn":"往往；大多","ex":{"en":"Old houses are often damp.","cn":"老房子大多都潮湿。"}}]},"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"常常；经常","en":"If something often happens, it happens many times or much of the time.","ex":{"en":"They often spent Christmas at Prescott Hill","cn":"他们经常在普雷斯科特山过圣诞节。"}},{"pos":"ADV 副词","cn":"（用于询问或说明某事发生的频率）（多）常","en":"You use how often to ask questions about frequency. You also use often in reported clauses and other statements to give information about the frequency of something.","ex":{"en":"How often do you brush your teeth?","cn":"你多久刷一次牙？"}},{"pos":"PHRASE 短语","cn":"（有规律地）有时，偶尔","en":"If something happens every so often, it happens regularly, but with fairly long intervals between each occasion.","ex":{"en":"She's going to come back every so often","cn":"她会偶尔回来的。"}},{"pos":"PHRASE 短语","cn":"往往；多半；通常","en":"If you say that something happens as often as not, or more often than not, you mean that it happens fairly frequently, and that this can be considered as typical of the kind of situation you are talking about.","ex":{"en":"Yet, as often as not, they find themselves the target of persecution rather than praise","cn":"然而，他们发现自己往往不是被赞扬而是遭刁难。"}}]},"examples":[{"en":"It is not often that you get such an opportunity.","cn":"你得到这样的机会，可不是常有的事。"},{"en":"All too often the animals die through neglect.","cn":"动物因缺乏照料而死亡的事司空见惯。"}]},"of":{"media":{"uk":"media/uk/of__gb_1.mp3","us":"media/us/of__us_1.mp3"},"oxford":{"phon":"əv","pos":"preposition","senses":[{"en":"belonging to somebody; relating to somebody","cn":"属于（某人）；关于（某人）","ex":{"en":"a friend of mine","cn":"我的一个朋友"}},{"en":"belonging to something; being part of something; relating to something","cn":"属于（某物）；（某事）部分的；关于（某物）","ex":{"en":"the lid of the box","cn":"盒子盖"}},{"en":"coming from a particular background or living in a place","cn":"出身于（某背景）；住在（某地）","ex":{"en":"a woman of Italian descent","cn":"意大利裔女子"}},{"en":"relating to or showing somebody/something","cn":"关于，反映（某人或某事）","ex":{"en":"a story of passion","cn":"热情洋溢的爱情故事"}},{"en":"used to say what somebody/something is, consists of or contains","cn":"（用于表示性质、组成或涵盖）即，由…组成","ex":{"en":"the city of Dublin","cn":"都柏林市"}},{"en":"used with measurements and expressions of time, age, etc.","cn":"（用于表示计量、时间或年龄等）","lab":"old-fashioned","ex":{"en":"2 kilos of potatoes","cn":"两公斤马铃薯"}},{"en":"used to show somebody/something belongs to a group, often after some, a few, etc.","cn":"（常用在 some、a few 等词语之后，表示人或物的所属）属于…的","ex":{"en":"some of his friends","cn":"他的几位朋友"}},{"en":"used to show the position of something/somebody in space or time","cn":"（表示人或事的时空位置）在，当","lab":"North American English","ex":{"en":"just north of Detroit","cn":"就在底特律以北"}},{"en":"used after nouns formed from verbs. The noun after ‘of’ can be either the object or the subject of the action.","cn":"（用于由动词转化的名词之后，of 之后的名词可以是受动者，也可以是施动者）","ex":{"en":"the arrival of the police (= they arrive)","cn":"警察的到来"}},{"en":"used after some verbs before mentioning somebody/something involved in the action","cn":"（用于某些动词后，后接动作所涉及的人或事）","ex":{"en":"to deprive somebody of something","cn":"剥夺某人的东西"}},{"en":"used after some adjectives before mentioning somebody/something that a feeling relates to","cn":"（用于某些形容词后，后接与感情相关的人或事）因为，由于","ex":{"en":"to be proud of something","cn":"为某事自豪"}},{"en":"used to give your opinion of somebody’s behaviour","cn":"（用于对某人的行为发表看法）","ex":{"en":"It was kind of you to offer.","cn":"感谢你的好意。"}},{"en":"used when one noun describes a second one","cn":"（用于一个名词修饰另一个名词时）","ex":{"en":"Where's that idiot of a boy (= the boy that you think is stupid)?","cn":"那个傻小子在哪儿？"}}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"（用于连接两个名词，其中前者表示后者的特定方面）","en":"You use of to combine two nouns when the first noun identifies the feature of the second noun that you want to talk about.","ex":{"en":"The average age of the women interviewed was only 21.5.","cn":"参加面试的女性平均年龄才21.5岁。"}},{"pos":"PREP 介词","cn":"（用于连接两个名词或名词与现在分词，其中后者对前者进行界定或补充信息）","en":"You use of to combine two nouns, or a noun and a present participle, when the second noun or present participle defines or gives more information about the first noun.","ex":{"en":"Would you say what you felt was a feeling of betrayal?","cn":"你是否觉得有一种被人出卖的感觉？"}},{"pos":"PREP 介词","cn":"（用于指称动作的名词后说明该动作的对象或主体）","en":"You use of after nouns referring to actions to specify the person or thing that is affected by the action or that performs the action. For example, 'the kidnapping of the child' refers to an action affecting a child; 'the arrival of the next train' refers to an action performed by a train.","ex":{"en":"...the reduction of trade union power inside the party.","cn":"党内工会权力的削弱"}},{"pos":"PREP 介词","cn":"（用于指称数量或组群的词和短语后表示计量的对象）","en":"You use of after words and phrases referring to quantities or groups of things to indicate the substance or thing that is being measured.","ex":{"en":"...7.6 litres of pure alcohol.","cn":"7.6升纯酒精"}},{"pos":"PREP 介词","cn":"（用于人或事物的名称后引出其所属或相关的机构或地方）","en":"You use of after the name of someone or something to introduce the institution or place they belong to or are connected with.","ex":{"en":"...the Prince of Wales.","cn":"威尔士亲王"}},{"pos":"PREP 介词","cn":"（用于指称容器的名词后，说明容器及其所含物）","en":"You use of after a noun referring to a container to form an expression referring to the container and its contents.","ex":{"en":"We could all do with a cup of tea","cn":"要是能给我们都来杯茶就好了。"}},{"pos":"PREP 介词","cn":"（用在可数名词后、不可数名词前表示某一单个物品）","en":"You use of after a count noun and before an uncount noun when you want to talk about an individual piece or item.","ex":{"en":"...a blade of grass","cn":"一片草叶"}},{"pos":"PREP 介词","cn":"（表示材料或成分）由…制成（或组成）的","en":"You use of to indicate the materials or things that form something.","ex":{"en":"...local decorations of wood and straw.","cn":"用木头和稻草制成的本地饰品"}},{"pos":"PREP 介词","cn":"（用于名词后表示其为某事物的一部分）","en":"You use of after a noun which specifies a particular part of something, to introduce the thing that it is a part of.","ex":{"en":"...the other side of the square","cn":"广场另一侧"}},{"pos":"PREP 介词","cn":"（用于某些动词后表示动作所涉及的人或事物）关于，由于","en":"You use of after some verbs to indicate someone or something else involved in the action.","ex":{"en":"He'd been dreaming of her","cn":"他一直梦见她。"}},{"pos":"PREP 介词","cn":"（用于某些形容词后表示与情感或特性相关的事物）对，为","en":"You use of after some adjectives to indicate the thing that a feeling or quality relates to.","ex":{"en":"I have grown very fond of Alec","cn":"我越来越喜欢亚力克。"}},{"pos":"PREP 介词","cn":"（用于指称施动者的单词前说明对该动作的看法）出自…，在…一方","en":"You use of before a word referring to the person who performed an action when saying what you think about the action.","ex":{"en":"This has been so nice, so terribly kind of you","cn":"您这么做真是太好心，太令我们感激不尽了。"}},{"pos":"PREP 介词","cn":"（用于描述名词后引出所指的人或事物）","en":"You use of after a noun which describes someone or something, to introduce the person or thing you are talking about.","ex":{"en":"...an awkward, slow-moving giant of a man.","cn":"举止笨拙、行动迟缓的巨人般的男子"}},{"pos":"PREP 介词","cn":"（表示程度）更大/较小程度上的…","en":"If something is more of or less of a particular thing, it is that thing to a greater or smaller degree.","ex":{"en":"Your extra fat may be more of a health risk than you realize","cn":"多余的脂肪对健康的威胁可能比你意识到的要大。"}},{"pos":"PREP 介词","cn":"（表示某人或某事物具有的特点或特性）","en":"You use of to indicate a characteristic or quality that someone or something has.","ex":{"en":"...the worth of their music.","cn":"他们音乐的价值"}},{"pos":"PREP 介词","cn":"（用于be动词后表示某人或某事物具有的特点或特性）","en":"You use of after the verb 'be' to indicate a characteristic or quality that someone or something has.","ex":{"en":"The crisis faced over the next few months is of an entirely different scale","cn":"接下来几个月内将要面临的危机规模将是无法相比的。"}},{"pos":"PREP 介词","cn":"（用于说明数量、价值或年龄）","en":"You use of to specify an amount, value, or age.","ex":{"en":"Last Thursday, Nick announced record revenues of $3.4 billion","cn":"上个星期四，尼克宣布公司收入创下34亿美元的纪录。"}},{"pos":"PREP 介词","cn":"（用于年、月等名词后表示状态或活动的持续时间）","en":"You use of after a noun such as 'month' or 'year' to indicate the length of time that some state or activity continues.","ex":{"en":"...eight bruising years of war","cn":"艰苦卓绝的8年战争"}},{"pos":"PREP 介词","cn":"（表示时间离某一钟点差几分）在…之前","en":"You can use of to say what time it is by indicating how many minutes there are before the hour mentioned.","ex":{"en":"At about a quarter of eight in the evening Joe Urber calls","cn":"大约晚上8点差一刻的时候，乔·乌尔贝尔打来电话。"}}]},"examples":[{"en":"Can't you throw out that old bike of Tommy's?","cn":"难道你就不能把汤米那辆旧自行车给扔掉？"},{"en":"He was cleared of all blame.","cn":"他所受的一切责难都澄清了。"}]},"offence":{"oxford":{"phon":"əˈfens","pos":"noun","senses":[{"en":"an illegal act","cn":"违法行为；犯罪；罪行","g":"[countable]","ex":{"en":"a criminal/serious/minor/sexual offence","cn":"刑事罪；重罪；轻罪；性犯罪"}},{"en":"the feeling of being upset or angry at something that somebody has said or done","cn":"（某人的言行导致的）冒犯，不快，反感","g":"[uncountable]","ex":{"en":"The photo may cause offence to some people.","cn":"这张照片可能会引起一些人的反感。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"违法行为；罪行","en":"An offence is a crime that breaks a particular law and requires a particular punishment.","ex":{"en":"Thirteen people have been charged with treason — an offence which can carry the death penalty","cn":"13人被控犯有叛国罪——一种可处死刑的罪行。"}},{"pos":"N-VAR 可变名词","cn":"冒犯；得罪","en":"Offence or an offence is behaviour which causes people to be upset or embarrassed.","ex":{"en":"The book might be published without creating offense","cn":"出版这本书可能不会引起人们的反感。"}},{"pos":"N-SING 单数名词","cn":"（体育运动中的）进攻队，进攻方","en":"In sports such as American football or basketball, the offense is the team which has possession of the ball and is trying to score.","ex":{"en":"Between plays the coach was talking to the offense in the huddle.","cn":"中场时，这位教练对围拢一圈的进攻队员进行战术指导。"}},{"pos":"PHRASE 短语","cn":"冒犯；得罪；惹恼","en":"If you cause offence or give offence to someone, you say or do something rude which upsets or embarrasses them.","ex":{"en":"It says the photograph is likely cause distress and offence to the public","cn":"上面说这张照片可能引起公众的忧虑和反感。"}},{"pos":"CONVENTION 惯用语","cn":"别见怪；无冒犯之意","en":"Some people say 'no offence' to make it clear that they do not want to upset you, although what they are saying may seem rather rude.","ex":{"en":"Dad, you need a bath. No offence.","cn":"爸爸，别见怪，不过你该洗澡了。"}},{"pos":"PHRASE 短语","cn":"（常指不必要地）(对…)生气，(因…)见怪","en":"If someone takes offence at something you say or do, they feel upset, often unnecessarily, because they think you are being rude to them.","ex":{"en":"She never takes offence at anything","cn":"什么事都不会让她生气。"}}]},"media":{"uk":"media/uk/offence__gb_1.mp3","us":"media/us/offence__us_1.mp3"},"examples":[{"en":"No offence, but I'd really like to be on my own.","cn":"我无意冒犯，但我确实想自己一个人待着。"},{"en":"The photo may cause offence to some people.","cn":"这张照片可能会引起一些人的反感。"}]},"offering":{"media":{"uk":"media/uk/offering__gb_1.mp3","us":"media/us/offering__us_1.mp3"},"oxford":{"phon":"ˈɒfərɪŋ","pos":"noun","senses":[{"en":"something that is produced for other people to use, watch, enjoy, etc.","cn":"用品；剧作；作品；供消遣的产品","ex":{"en":"the latest offering from the Canadian-born writer","cn":"在加拿大出生的那位作家的最新作品"}},{"en":"something that is given to a god as part of a religious ceremony","cn":"祭品；供品","ex":{"en":"They made sacrificial offerings to the gods.","cn":"他们向诸神献上了祭品。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"待售品；出售品","en":"An offering is something that is specially produced to be sold.","ex":{"en":"It was very, very good, far better than vegetarian offerings in many a posh restaurant.","cn":"这道菜真是人间美味，远远超过很多豪华餐厅的素食菜品。"}},{"pos":"N-COUNT 可数名词","cn":"祭品；供品","en":"An offering is a gift that people offer to their God or gods as a form of worship.","ex":{"en":"...the holiest of the Shinto rituals, where offerings are made at night to the great Sun.","cn":"神道教仪式中最神圣的时刻，即在晚间祭祀“天照大神”太阳神"}}]},"examples":[{"en":"the latest offering from the Canadian-born writer","cn":"在加拿大出生的那位作家的最新作品"},{"en":"the latest offering from Nanci Griffith","cn":"南希•格里菲思的最新作品"}],"base":"offer"},"offset":{"media":{"uk":"media/uk/offset__gb_1.mp3","us":"media/us/offset__us_1.mp3"},"oxford":{"phon":"ˈɒfset","pos":"verb","senses":[{"en":"to use one cost, payment or situation in order to cancel or reduce the effect of another","cn":"抵消；弥补；补偿","lab":"British English","ex":{"en":"Prices have risen in order to offset the increased cost of materials.","cn":"为补偿原料成本的增加而提高了价格。"}},{"en":"used to describe a method of printing in which ink (= coloured liquid) is put onto a metal plate, then onto a rubber surface and only then onto the paper","cn":"胶印的","pos":"adjective"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"抵消；补偿","en":"If one thing is offset by another, the effect of the first thing is reduced by the second, so that any advantage or disadvantage is cancelled out.","ex":{"en":"The increase in pay costs was more than offset by higher productivity","cn":"提高的生产率抵消了增加的工资成本后仍有结余。"}}]},"examples":[{"en":"Prices have risen in order to offset the increased cost of materials.","cn":"为补偿原料成本的增加而提高了价格。"},{"en":"( BrE ) What expenses can you offset against tax?","cn":"什么开支可以获得税项减免？"}]},"off-street":{"oxford":{"phon":"ˈɒf striːt","pos":"adjective","senses":[{"en":"not on the public road","cn":"不在大街上的；大街以外的；路外的；后街的","ex":{"en":"an apartment with off-street parking","cn":"后街街边可停车的公寓"}}]},"media":{"uk":"media/uk/off_street_1_gb_1.mp3","us":"media/us/off_street_1_us_1.mp3"},"examples":[{"en":"an apartment with off-street parking","cn":"有后街街边可停车的公寓"}]},"offend":{"oxford":{"phon":"əˈfend","pos":"verb","senses":[{"en":"to make somebody feel upset because of something you say or do that is rude or embarrassing","cn":"得罪；冒犯","g":"[transitive, often passive, intransitive]","ex":{"en":"They'll be offended if you don't go to their wedding.","cn":"你若不参加他们的婚礼，他们会生气的。"}},{"en":"to seem unpleasant to somebody","cn":"令人不适","g":"[transitive]","ex":{"en":"The smell from the farm offended some people.","cn":"农场散发的气味让一些人闻了不舒服。"}},{"en":"to commit a crime or crimes","cn":"犯罪；犯法","g":"[intransitive]","lab":"formal","ex":{"en":"He started offending at the age of 16.","cn":"他 16 岁就开始犯法。"}},{"en":"to be against what people believe is morally right","cn":"违背（人情）；违反（常理）；有悖于","g":"[intransitive]","lab":"formal","ex":{"en":"comments that offend against people’s religious beliefs","cn":"有悖人民宗教信仰的评论"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"冒犯；得罪；触怒","en":"If you offend someone, you say or do something rude which upsets or embarrasses them.","ex":{"en":"He apologizes for his comments and says he had no intention of offending the community","cn":"他为自己发表的评论道歉并称无意冒犯该社群。"}},{"pos":"VERB 动词","cn":"违反，违犯，违背（法律、规定、原则等）","en":"To offend against a law, rule, or principle means to break it.","ex":{"en":"This bill offends against good sense and against justice","cn":"该法案有悖于理智和公正。"}},{"pos":"VERB 动词","cn":"犯罪；犯法","en":"If someone offends, they commit a crime.","ex":{"en":"In Western countries girls are far less likely to offend than boys.","cn":"在西方国家，女孩的犯罪倾向远低于男孩。"}}]},"media":{"uk":"media/uk/offend__gb_1.mp3","us":"media/us/offend__us_1.mp3"},"examples":[{"en":"They'll be offended if you don't go to their wedding.","cn":"你若不参加他们的婚礼，他们会生气的。"},{"en":"The smell from the farm offended some people.","cn":"农场散发的气味让一些人闻了不舒服。"}]},"official":{"media":{"uk":"media/uk/official__gb_1.mp3","us":"media/us/official__us_1.mp3"},"oxford":{"phon":"əˈfɪʃl","pos":"adjective","senses":[{"en":"agreed to, said, done, etc. by somebody who is in a position of authority","cn":"正式的；官方的；官方授权的","g":"[usually before noun]","ex":{"en":"an official announcement/decision/statement","cn":"官方公告／决定／声明"}},{"en":"connected with the job of somebody who is in a position of authority","cn":"公务的；公职的；公事的","g":"[only before noun]","ex":{"en":"official duties/responsibilities","cn":"公务"}},{"en":"formal and attended by people in authority","cn":"正式的；公务的；官方场合的","g":"[only before noun]","ex":{"en":"an official function/reception","cn":"官方活动／招待会"}},{"en":"that is told to the public but may not be true","cn":"公开的；公布的；据官方的","g":"[only before noun]","ex":{"en":"I only knew the official version of events.","cn":"我对事情的了解仅限于官方的版本。"}},{"en":"a person who is in a position of authority in a large organization","cn":"要员；官员；高级职员","ex":{"en":"She is the government official in charge of the project.","cn":"她是负责该项目的政府官员。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"官方的；正式的","en":"Official means approved by the government or by someone in authority.","ex":{"en":"According to the official figures, over one thousand people died during the revolution","cn":"根据官方数字，1,000多人在这场革命中丧生。"}},{"pos":"ADJ 形容词","cn":"公务的；公职的；公事的","en":"Official activities are carried out by a person in authority as part of their job.","ex":{"en":"The President is in Brazil for an official two-day visit.","cn":"总统正在巴西进行为期两天的正式访问。"}},{"pos":"ADJ 形容词","cn":"官员（因职务使用）的","en":"Official things are used by a person in authority as part of their job.","ex":{"en":"...the official residence of the Head of State.","cn":"国家元首的官邸"}},{"pos":"ADJ 形容词","cn":"（解释、理由等）冠冕堂皇的，桌面上的","en":"If you describe someone's explanation or reason for something as the official explanation, you are suggesting that it is probably not true, but is used because the real explanation is embarrassing.","ex":{"en":"The official explanation for the cancellation of the party conference is that there are no premises available","cn":"官方对取消此次政党会议作出的解释是没有场地。"}},{"pos":"N-COUNT 可数名词","cn":"官员；行政人员；高级职员","en":"An official is a person who holds a position of authority in an organization.","ex":{"en":"A senior UN official hopes to visit Baghdad this month.","cn":"一位联合国高级官员希望于本月访问巴格达。"}},{"pos":"N-COUNT 可数名词","cn":"（体育比赛中的）裁判员，执法人","en":"An official at a sports event is a referee, umpire, or other person who checks that the players follow the rules."}]},"examples":[{"en":"He made an official visit to Tokyo in March.","cn":"他于三月到东京进行了一次公务访问。"},{"en":"I only knew the official version of events.","cn":"我对事情的了解仅限于官方的版本。"}]},"offer":{"media":{"uk":"media/uk/offer__gb_1.mp3","us":"media/us/offer__us_1.mp3"},"oxford":{"phon":"ˈɒfə(r)","pos":"verb","senses":[{"en":"to say that you are willing to give something to somebody","cn":"主动提供，主动给予（某事物）","g":"[transitive, intransitive]","lab":"British English or formal, North American English，，","ex":{"en":"Josie had offered her services as a guide.","cn":"乔西曾表示愿意当向导。"}},{"en":"to say that you are willing to do something for somebody","cn":"主动提出，主动分担（做某事）","g":"[transitive, intransitive]","ex":{"en":"The kids offered to do the dishes.","cn":"孩子们主动要求洗盘子。"}},{"en":"to make something available for sale or use","cn":"提供，供应（产品、服务等）","g":"[transitive]","ex":{"en":"The hotel offers excellent facilities for families.","cn":"本旅馆提供适合家庭的优良设施。"}},{"en":"to provide the opportunity for something; to provide access to something","cn":"提供（机会或权利）","g":"[transitive]","ex":{"en":"The job didn't offer any prospects for promotion.","cn":"这份工作没有任何升迁的希望。"}},{"en":"to show that you are ready to resist or attack somebody/something","cn":"表现出抵抗力（或攻击力）","g":"[transitive]","ex":{"en":"Universities offered little resistance to these changes.","cn":"大学对这些变化几乎毫无抵抗力。"}},{"en":"to give something to God","cn":"奉献，祭献（给上帝）","g":"[transitive]","lab":"formal","ex":{"en":"We offered up our prayers for the men's safe return.","cn":"我们祈求上苍保佑他们平安归来。"}},{"en":"an act of saying that you are willing to do something for somebody or give something to somebody","cn":"主动提议；建议","ex":{"en":"to receive a job offer","cn":"收到聘用邀约"},"pos":"noun"},{"en":"an amount of money that somebody is willing to pay for something","cn":"出价；报价","ex":{"en":"I've had an offer of $2 500 for the car.","cn":"有人向我出价 2 500 美元买这辆汽车。"},"pos":"noun"},{"en":"a reduction in the normal price of something, usually for a short period of time","cn":"（通常为短期的）减价，削价；处理价；特价","ex":{"en":"This special offer is valid until the end of the month.","cn":"这个特价优惠月底前有效。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"提供；给予","en":"If you offer something to someone, you ask them if they would like to have it or use it.","ex":{"en":"He has offered seats at the conference table to the Russian leader and the president of Kazakhstan","cn":"他已邀请俄罗斯领导人和哈萨克斯坦总统参加会谈。"}},{"pos":"VERB 动词","cn":"（主动）表示愿意（做某事）；提议","en":"If you offer to do something, you say that you are willing to do it.","ex":{"en":"Peter offered to teach them water-skiing","cn":"彼得主动提出教他们滑水。"}},{"pos":"N-COUNT 可数名词","cn":"提供（物）；给予（物）；提议","en":"An offer is something that someone says they will give you or do for you.","ex":{"en":"The offer of talks with Moscow marks a significant change from the previous western position","cn":"提议与莫斯科举行会谈标志着西方立场的重大转变。"}},{"pos":"VERB 动词","cn":"提供（信息、建议等）；作出（表扬）","en":"If you offer someone information, advice, or praise, you give it to them, usually because you feel that they need it or deserve it.","ex":{"en":"They manage a company offering advice on mergers and acquisitions","cn":"他们经营着一家为兼并收购业务提供咨询的公司。"}},{"pos":"VERB 动词","cn":"给予，表示（爱、友谊等）","en":"If you offer someone something such as love or friendship, you show them that you feel that way towards them.","ex":{"en":"The President has offered his sympathy to the Georgian people","cn":"总统对格鲁吉亚人民表示了同情。"}},{"pos":"VERB 动词","cn":"（向上帝或神）奉献（祈祷、赞美），祭献（牺牲）","en":"If people offer prayers, praise, or a sacrifice to God or a god, they speak to or give something to their god.","ex":{"en":"Church leaders offered prayers and condemned the bloodshed","cn":"教会领袖向上帝祈祷并谴责流血事件。"}},{"pos":"VERB 动词","cn":"（机构等）提供，给予（服务、产品等）","en":"If an organization offers something such as a service or product, it provides it.","ex":{"en":"We have been successful because we are offering a quality service","cn":"我们因提供的服务水准一流一直经营得很成功。"}},{"pos":"N-COUNT 可数名词","cn":"（商品的）特价，特惠","en":"An offer in a shop is a specially low price for a specific product or something extra that you get if you buy a certain product.","ex":{"en":"This month's offers include a shirt, trousers and bed covers","cn":"本月的特价商品包括一款衬衫、裤子和多种床罩。"}},{"pos":"VERB 动词","cn":"（买方）出（价），开（价）","en":"If you offer a particular amount of money for something, you say that you will pay that much to buy it.","ex":{"en":"Whitney has offered $21.50 a share in cash for 49.5 million Prime shares","cn":"惠特尼公司开出每股21.50美元的现金价收购4,950 万股普赖姆公司的股票。"}},{"pos":"N-COUNT 可数名词","cn":"（买方的）报价，开价；赔偿金","en":"An offer is the amount of money that someone says they will pay to buy something or give to someone because they have harmed them in some way.","ex":{"en":"The lawyers say no one else will make me an offer","cn":"律师说不会再有人给我出价了。"}},{"pos":"PHRASE 短语","cn":"具有某种品质（或能力）","en":"If you have something to offer, you have a quality or ability that makes you important, attractive, or useful.","ex":{"en":"In your free time, explore all that this incredible city has to offer.","cn":"您可以在闲暇时间探索这座美妙城市的各种风情。"}},{"pos":"PHRASE 短语","cn":"提供的；供使用的；待售的","en":"If there is something on offer, it is available to be used or bought.","ex":{"en":"Savings schemes are the best retail investment products on offer.","cn":"储蓄方案是现有的最佳零售投资产品。"}},{"pos":"PHRASE 短语","cn":"愿意考虑买方出价；愿意接受合理报价","en":"If you are open to offers, you are willing to do something if someone will pay you an amount of money that you think is reasonable.","ex":{"en":"It seems that while the Kiwis are keen to have him, he is still open to offers.","cn":"看来尽管新西兰几维队很想与他签约，他仍然欢迎其他球队开价。"}},{"pos":"","cn":"","en":"相关词组：offer up"}]},"examples":[{"en":"I don't think they need help, but I think I should offer anyway.","cn":"我想他们不需要帮助，但我认为我还是应该主动提出来。"},{"en":"The original price was £3 000, but I'm open to offers (= willing to consider offers that are less than that).","cn":"原价为 3 000 英镑，但价钱还可以商量。"}]},"office":{"media":{"img":["media/pic/office_labels_comp.jpg","media/thumb/office.jpg"],"uk":"media/uk/office__gb_1.mp3","us":"media/us/office__us_1.mp3"},"oxford":{"phon":"ˈɒfɪs","pos":"noun","senses":[{"en":"a room, set of rooms or building where people work, usually sitting at desks","cn":"办公室；办公楼","g":"[countable]","lab":"British English","sc":"room/building","ex":{"en":"The company is moving to new offices on the other side of town.","cn":"公司要迁往城另一边的新办公楼。"}},{"en":"a room in which a particular person works, usually at a desk","cn":"（某人的）办公室","g":"[countable]","sc":"room/building","ex":{"en":"Some people have to share an office.","cn":"有些人只好合用一间办公室。"}},{"en":"a place where a doctor, dentist or vet sees patients","cn":"诊室；门诊处","g":"[countable]","lab":"North American English","sc":"room/building","ex":{"en":"a doctor’s/dentist’s office","cn":"诊室；牙医诊所"}},{"en":"a room or building used for a particular purpose, especially to provide information or a service","cn":"办事处；（尤指）问询处，服务处","g":"[countable]","sc":"room/building","ex":{"en":"a ticket office","cn":"售票处"}},{"en":"used in the names of some British government departments","cn":"（用于英国某些政府部门的名称中）","g":"[countable]","sc":"government department","ex":{"en":"the Home Office","cn":"内政部"}},{"en":"an important position of authority, especially in government; the work and duties connected with this","cn":"要职；重要官职；重要职务","g":"[uncountable, countable]","lab":"especially North American English","sc":"important position","ex":{"en":"She held office as a cabinet minister for ten years.","cn":"她担任内阁部长长达十年。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"办公室","en":"An office is a room or a part of a building where people work sitting at desks.","ex":{"en":"He had an office big enough for his desk and chair, plus his VDU","cn":"他有一间足以容纳书桌、椅子和视频显示器的办公室。"}},{"pos":"N-COUNT; N-IN-NAMES 名称名词；名称名词","cn":"（尤指政府的）部，局，厅","en":"An office is a department of an organization, especially the government, where people deal with a particular kind of administrative work.","ex":{"en":"Thousands have registered with unemployment offices.","cn":"已有数千人在失业管理处作了登记。"}},{"pos":"N-COUNT 可数名词","cn":"（问询、购票或提供服务的）处，所","en":"An office is a small building or room where people can go for information, tickets, or a service of some kind.","ex":{"en":"The tourist office operates a useful room-finding service.","cn":"这家旅游办事处提供十分实用的住宿查询服务。"}},{"pos":"N-COUNT 可数名词","cn":"诊所","en":"A doctor's or dentist's office is a place where a doctor or dentist sees their patients."},{"pos":"N-UNCOUNT 不可数名词","cn":"要职；公职；官职","en":"If someone holds office in a government, they have an important job or position of authority.","ex":{"en":"The events to mark the President's ten years in office went ahead as planned","cn":"总统任职10周年的庆祝活动按计划进行。"}},{"pos":"PHRASE 短语","cn":"帮助；协助","en":"Someone's good offices are the help that they give to other people who are trying to achieve something.","ex":{"en":"She sought the good offices of the President for the smooth passage of the Bill.","cn":"为了使该法案顺利通过，她寻求总统的帮助。"}}]},"examples":[{"en":"The present government took office in 2009.","cn":"现政府于 2009 年上台执政。"},{"en":"The company is moving to new offices on the other side of town.","cn":"公司要迁往城另一边的新办公楼。"}]},"oft":{"media":{"uk":"media/uk/oft__gb_1.mp3","us":"media/us/oft__us_1.mp3"},"oxford":{"phon":"ɒft","pos":"adverb","senses":[{"en":"often","cn":"经常"},{"en":"often","cn":"经常","ex":{"en":"an oft-repeated claim","cn":"一再重复的说法"},"pos":"prefix"}]}},"off":{"media":{"uk":"media/uk/off__gb_1.mp3","us":"media/us/off__us_1.mp3"},"oxford":{"phon":"ɒf","pos":"adverb","senses":[{"en":"used to say that something has been removed or become separated","cn":"（用以表示除去了某物）","ex":{"en":"He's had his beard shaved off.","cn":"他把胡子刮掉了。"}},{"en":"not connected or functioning","cn":"未连接；不工作","ex":{"en":"The water is off.","cn":"停水了。"}},{"en":"away from a place; at a distance in space or time","cn":"离开（某处）；（在空间或时间上）距，离","ex":{"en":"I called him but he ran off.","cn":"我喊他，可他跑开了。"}},{"en":"away from work or duty","cn":"休假；休息","ex":{"en":"She's off today.","cn":"她今天休假。"}},{"en":"starting a race","cn":"起跑","ex":{"en":"They're off (= the race has begun).","cn":"他们起跑了。"}},{"en":"taken from the price","cn":"减价的；削价的","ex":{"en":"shoes with $20 off","cn":"减价 20 美元的鞋"}},{"en":"no longer going to happen; cancelled","cn":"不再会发生；被取消","ex":{"en":"The wedding is off.","cn":"婚礼被取消了。"}},{"en":"no longer available or being served","cn":"没有；不再供应","lab":"especially British English","ex":{"en":"Sorry, the duck is off.","cn":"对不起，鸭子卖光了。"}},{"en":"behind or at the sides of the stage in a theatre","cn":"在剧院舞台的后面（或旁边）"},{"en":"down or away from a place or at a distance in space or time","cn":"从（某处）落下；离开；（时空上）离，距","ex":{"en":"I fell off the ladder.","cn":"我从梯子上跌了下来。"},"pos":"preposition"},{"en":"used to say that something has been removed","cn":"从…去掉；从…移开","ex":{"en":"You need to take the top off the bottle first!","cn":"你得先把瓶盖子打开！"},"pos":"preposition"},{"en":"away from work or duty","cn":"休假；休息","ex":{"en":"He's had ten days off school.","cn":"他有十天没上学了。"},"pos":"preposition"},{"en":"away from a price","cn":"偏离…价格；削价；杀价","ex":{"en":"They knocked £500 off the car.","cn":"他们对这辆汽车杀价 500 英镑。"},"pos":"preposition"},{"en":"leading away from something, for example a road or room","cn":"离开；偏离","ex":{"en":"We live off Main Street.","cn":"我们住在大街附近。"},"pos":"preposition"},{"en":"from a person or place","cn":"从某人（或某地）","lab":"informal","ex":{"en":"I got this off a website somewhere.","cn":"这是我从某个网站上找到的。"},"pos":"preposition"},{"en":"off; from","cn":"离开；来源于；从","lab":"non-standard or North American English, informal，，","ex":{"en":"She jumped off of the wall.","cn":"她从墙上跳了下来。"},"pos":"preposition"},{"en":"not wanting or liking something that you usually eat or use","cn":"不想；戒除","ex":{"en":"I'm off (= not drinking) alcohol for a week.","cn":"我有一星期没喝酒了。"},"pos":"preposition"},{"en":"no longer fresh enough to eat or drink","cn":"不新鲜；变质","lab":"British English","ex":{"en":"This fish has gone off.","cn":"这条鱼已变质了。"},"pos":"adjective"},{"en":"not polite or friendly","cn":"不礼貌；不热情；冷淡","lab":"informal, especially British English，，","ex":{"en":"He was a bit off with me this morning.","cn":"他今天早晨对我有点冷淡。"},"pos":"adjective"},{"en":"not acceptable","cn":"不能接受；难以容忍；不行","lab":"informal, especially British English，，","ex":{"en":"It's a bit off expecting us to work on Sunday.","cn":"让我们星期天上班工作，那可不太行吧。"},"pos":"adjective"},{"en":"the start of a race","cn":"起跑","ex":{"en":"They're ready for the off.","cn":"他们准备起跑了。"},"pos":"noun"},{"en":"to kill somebody","cn":"杀死（某人）","pos":"verb"},{"en":"not on; away from","cn":"不在…上；离开；去掉","ex":{"en":"offstage","cn":"幕后的"},"pos":"prefix"}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"从…移开；从…脱离","en":"If something is taken off something else or moves off it, it is no longer touching that thing.","ex":{"en":"He took his feet off the desk","cn":"他把脚从桌上移开。"}},{"pos":"PREP 介词","cn":"从（交通工具）上下来","en":"When you get off a bus, train, or plane, you come out of it or leave it after you have been travelling on it.","ex":{"en":"Don't try to get on or off a moving train!","cn":"火车运行时请勿上下车！"}},{"pos":"PREP 介词","cn":"不去,不涉足（某处）","en":"If you keep off a street or piece of land, you do not step on it or go there.","ex":{"en":"Locking up men does nothing more than keep them off the streets","cn":"把这些人关起来只是做到了不让他们上街而已。"}},{"pos":"PREP 介词","cn":"离（某地）不远；在…附近","en":"If something is situated off a place such as a coast, room, or road, it is near to it or next to it, but not exactly in it.","ex":{"en":"The boat was anchored off the northern coast of the peninsula","cn":"这艘船停泊在离该半岛北部海岸不远的地方。"}},{"pos":"ADV 副词","cn":"离开","en":"If you go off, you leave a place.","ex":{"en":"He was just about to drive off when the secretary came running out","cn":"他正打算驾车离开，这时秘书跑了出来。"}},{"pos":"ADV 副词","cn":"（用于非正式及有时具冒犯性的短语动词）（走）开，（滚）开","en":"Off is used in a number of informal and sometimes offensive phrasal verbs, such as buzz off ,clear off, or in British English bugger off, which are used to tell someone angrily to go away."},{"pos":"ADV 副词","cn":"（脱）掉（衣服）；（取）下（首饰）","en":"When you take off clothing or jewellery that you are wearing, you remove it from your body.","ex":{"en":"He took off his spectacles and rubbed frantically at the lens","cn":"他摘下眼镜，疯狂地擦着镜片。"}},{"pos":"ADV 副词","cn":"（因生病、放假等等）休息，不工作","en":"If you have time off or a particular day off, you do not go to work or school, for example because you are ill or it is a day when you do not usually work.","ex":{"en":"The rest of the men had the day off","cn":"其他人这天没上班。"}},{"pos":"PREP 介词","cn":"避开（某话题）","en":"If you keep off a subject, you deliberately avoid talking about it.","ex":{"en":"Keep off the subject of politics","cn":"勿谈政治。"}},{"pos":"ADV 副词","cn":"取消；中止","en":"If something such as an agreement or a sporting event is off, it is cancelled.","ex":{"en":"Until Pointon is completely happy, however, the deal's off","cn":"但是，在波因顿完全满意之前，这一协议不再作数。"}},{"pos":"PREP 介词","cn":"停服，停用（药物等）；戒…","en":"If someone is off something harmful such as a drug, they have stopped taking or using it.","ex":{"en":"She felt better and the psychiatrist took her off drug therapy","cn":"她感觉好些了，那位精神科医生让她停止了药物治疗。"}},{"pos":"PREP 介词","cn":"不再喜欢；不再想","en":"If you are off something, you have stopped liking it.","ex":{"en":"I'm off coffee at the moment","cn":"我眼下不再嗜咖啡了。"}},{"pos":"ADV 副词","cn":"（机器、电灯等）关掉，停掉，不再运转","en":"When something such as a machine or electric light is off, it is not functioning or in use. When you switch it off, you stop it functioning.","ex":{"en":"As he pulled into the driveway, he saw her bedroom light was off","cn":"当他把车开进车道时，他看到她卧室的灯已经熄了。"}},{"pos":"PREP 介词","cn":"（价格）减掉，降低","en":"If there is money off something, its price is reduced by the amount specified.","ex":{"en":"...Simons Leatherwear, 37 Old Christchurch Road. 20 per cent off all jackets this Saturday.","cn":"本周六老基督堂路37号的西蒙斯皮衣店所有夹克降价20％。"}},{"pos":"ADV 副词","cn":"（空间上）离，距","en":"If something is a long way off, it is a long distance away from you.","ex":{"en":"Florida was a long way off","cn":"佛罗里达离这儿很远。"}},{"pos":"ADV 副词","cn":"（时间上）离，距","en":"If something is a long time off, it will not happen for a long time.","ex":{"en":"An end to the crisis seems a long way off","cn":"这场危机看来远未结束。"}},{"pos":"PREP 介词","cn":"从…（获得）","en":"If you get something off someone, you obtain it from them.","ex":{"en":"I don't really get a lot of information, and if I do I get it off Mark","cn":"我得到的信息其实不多，即使有也是马克告诉我的。"}},{"pos":"COMB in ADJ-GRADED","cn":"（与well,badly,worse等副词连用构成形容词）表示“处于…境况的”","en":"Off combines with adverbs such as 'well', 'badly', and 'worse' to form adjectives that indicate how poor or rich someone is.","ex":{"en":"Most of these people aren't very well off","cn":"这些人大都不算太富裕。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（食物）腐坏的，变质的，变味的","en":"If food has gone off, it tastes and smells bad because it is no longer fresh enough to be eaten.","ex":{"en":"Don't eat that! It's mouldy. It's gone off!","cn":"别吃那个！它已经发霉变质了！"}},{"pos":"PREP 介词","cn":"依靠（食物、钱等生存）","en":"If you live off a particular kind of food, you eat it in order to live. If you live off a particular source of money, you use it to live.","ex":{"en":"Her husband's memories are of living off roast chicken and drinking whisky","cn":"她丈夫只记得过去吃烤鸡、喝威士忌的日子。"}},{"pos":"PREP 介词","cn":"（机器）靠（某种燃料或动力运转）","en":"If a machine runs off a particular kind of fuel or power, it uses that power in order to function.","ex":{"en":"The Auto Compact Disc Cleaner can run off batteries or mains.","cn":"这种光盘自动清洗机可用电池或电源两种方式驱动。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（行为）过头的，不当的，无法接受的","en":"If you say that someone's behaviour is a bit off, you mean that you find it unacceptable or wrong.","ex":{"en":"...coming home with make-up all over his clothes — it's a bit off isn't it","cn":"衣服上到处沾着化妆品回到家——他这样有点过分了，是不是。"}},{"pos":"PHRASE 短语","cn":"偶尔；有时；断断续续地","en":"If something happens on and off, or off and on, it happens occasionally, or only for part of a period of time, not in a regular or continuous way.","ex":{"en":"I was still working on and off as a waitress to support myself","cn":"我为了糊口仍然间或去做服务员。"}}]},"examples":[{"en":"Families will be better off under the new law (= will have more money).","cn":"这项新法律将使每个家庭的经济较前宽裕。"},{"en":"The weather was so bad we'd have been better off staying at home.","cn":"天气太糟了，我们要是待在家里就好了。"}]},"offline":{"media":{"uk":"media/uk/offline__gb_1.mp3","us":"media/us/offline__us_2.mp3"},"oxford":{"phon":"ˌɒfˈlaɪn","pos":"adjective","senses":[{"en":"not directly controlled by or connected to a computer or to the internet","cn":"未联机的；未连线的；脱机的；离线的","ex":{"en":"For offline orders, call this number.","cn":"离线订货请拨打这个号码。"}},{"en":"without being directly controlled by or connected to a computer or to the internet","cn":"未联机的；未连线的；脱机的；离线的","ex":{"en":"How do I write an email offline?","cn":"我如何在离线时写电子邮件？"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"脱机的；离线的","en":"If a computer is offline, it is not connected to the Internet. →see: ;","ex":{"en":"Most software programs allow you to compose emails offline.","cn":"大部分软件程序允许用户在脱机状态下写电子邮件。off line"}}]},"examples":[{"en":"For offline orders, call this number.","cn":"离线订货请拨打这个号码。"},{"en":"How do I write an email offline?","cn":"如何在离线时写电子邮件？"}]},"officially":{"media":{"uk":"media/uk/officially__gb_1.mp3","us":"media/us/officially__us_1.mp3"},"oxford":{"phon":"əˈfɪʃəli","pos":"adverb","senses":[{"en":"publicly and by somebody who is in a position of authority","cn":"正式地；官方地；公开地","ex":{"en":"The library will be officially opened by the local MP.","cn":"图书馆将由当地下院议员正式揭幕。"}},{"en":"according to a particular set of rules, laws, etc.","cn":"依据法规等","ex":{"en":"Many of those living on the streets are not officially homeless.","cn":"根据法律定义，许多流浪街头的人并非无家可归者。"}},{"en":"according to information that has been told to the public but that may not be true","cn":"据传；据公布","ex":{"en":"Officially, he resigned because of bad health.","cn":"据官方说法，他是因健康状况不佳而辞职的。"}}]},"examples":[{"en":"Many of those living on the streets are not officially homeless.","cn":"根据法律定义，许多流浪街头的人并非无家可归者。"},{"en":"Officially, he resigned because of bad health.","cn":"据官方说法，他是因健康状况不佳而辞职的。"}]},"offensive":{"oxford":{"phon":"əˈfensɪv","pos":"adjective","senses":[{"en":"rude in a way that causes somebody to feel upset or annoyed because it shows a lack of respect","cn":"冒犯的；得罪人的；无礼的","ex":{"en":"offensive remarks","cn":"冒犯的言论"}},{"en":"extremely unpleasant","cn":"极其讨厌的；令人不适的","lab":"formal","ex":{"en":"The problem is how to eliminate offensive smells from the processing plant.","cn":"问题在于怎样才能消除加工厂那刺鼻的气味。"}},{"en":"connected with the act of attacking somebody/something","cn":"攻击性的；进攻性的","g":"[only before noun]","ex":{"en":"an offensive war","cn":"侵略战争"}},{"en":"connected with the team that has control of the ball; connected with the act of scoring points","cn":"攻方的；进攻型的；攻击型的","lab":"North American English, sport，，","ex":{"en":"offensive play","cn":"进攻打法"}},{"en":"a military operation in which large numbers of soldiers, etc. attack another country","cn":"进攻；攻击；侵犯","ex":{"en":"an air offensive","cn":"空中攻击"},"pos":"noun"},{"en":"a series of actions aimed at achieving something in a way that attracts a lot of attention","cn":"（引人注意的）系列行动；运动；攻势","ex":{"en":"The government has launched a new offensive against crime.","cn":"政府发动了新的打击犯罪攻势。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"冒犯的；得罪人的；唐突的;无礼的","en":"Something that is offensive upsets or embarrasses people because it is rude or insulting.","ex":{"en":"Some friends of his found the play horribly offensive.","cn":"他的一些朋友觉得该剧非常让人反感。"}},{"pos":"N-COUNT 可数名词","cn":"进攻","en":"A military offensive is a carefully planned attack made by a large group of soldiers.","ex":{"en":"Its latest military offensive against rebel forces is aimed at reopening important trade routes","cn":"它对叛军的最新一轮军事进攻旨在重新打开重要的贸易通道。"}},{"pos":"N-COUNT 可数名词","cn":"（表示愤怒或反对的）强硬行动","en":"If you conduct an offensive, you take strong action to show how angry you are about something or how much you disapprove of something.","ex":{"en":"Republicans acknowledged that they had little choice but to mount an all-out offensive on the Democratic nominee.","cn":"共和党人承认他们别无选择，只有对获提名的民主党人展开全面攻击。"}},{"pos":"ADJ 形容词","cn":"（体育运动中球队）进攻的，攻方的","en":"In sports such as American football or basketball, the offensive team is the team which has possession of the ball and is trying to score.","ex":{"en":"The worst-ever defeat of this team proved once again that Stanford can be one of the most explosive offensive teams in the country.","cn":"该队前所未有的惨败再次证明斯坦福队是国内最具爆发力的进攻型队伍之一。"}},{"pos":"PHRASE 短语","cn":"采取强势行动；采取攻势","en":"If you go on the offensive ,go over to the offensive, or take the offensive, you begin to take strong action against people who have been attacking you.","ex":{"en":"The West African forces went on the offensive in response to attacks on them","cn":"西非部队对袭击者展开全力还击。"}}]},"media":{"uk":"media/uk/offensive__gb_1.mp3","us":"media/us/offensive__us_1.mp3"},"examples":[{"en":"The public seems unconvinced by their latest charm offensive (= their attempt to make people like them).","cn":"公众似乎并不相信他们最近所表演的一连串笑脸攻势。"},{"en":"The programme contains language which some viewers may find offensive.","cn":"节目里使用了某些观众可能认为是犯忌的语言。"}]},"offends":{"lemma":"offend"},"offshoot":{"media":{"uk":"media/uk/offshoot__gb_1.mp3","us":"media/us/offshoot__us_1.mp3"},"oxford":{"phon":"ˈɒfʃuːt","pos":"noun","senses":[{"en":"a thing that develops from something, especially a small organization that develops from a larger one","cn":"分支；（尤指）分支机构","ex":{"en":"commercial offshoots of universities","cn":"大学附属的商业机构"}},{"en":"a new stem that grows on a plant","cn":"蘗枝；分枝","lab":"specialist"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"分支；衍生物","en":"If one thing is an offshoot of another, it has developed from that other thing.","ex":{"en":"Psychology began as a purely academic offshoot of natural philosophy","cn":"心理学最初是自然哲学一个纯粹的学术分支。"}}]},"examples":[{"en":"The company was originally an offshoot of Bell Telephones.","cn":"该公司原本是贝尔电话公司的一家分支机构。"},{"en":"the Mafia and its offshoots","cn":"黑手党组织及其分支"}]},"officer":{"media":{"uk":"media/uk/officer__gb_1.mp3","us":"media/us/officer__us_1.mp3"},"oxford":{"phon":"ˈɒfɪsə(r)","pos":"noun","senses":[{"en":"a person who is in a position of authority in the armed forces","cn":"军官","ex":{"en":"army/military/naval officers","cn":"陆军军官；军官；海军军官"}},{"en":"a member of the police","cn":"警察；警员","ex":{"en":"the officer in charge of the case","cn":"负责本案的警察"}},{"en":"a title for a police officer","cn":"警察的头衔","lab":"North American English","ex":{"en":"Officer Dibble","cn":"迪布尔警官"}},{"en":"a person who is in a position of authority in the government or a large organization","cn":"（政府或大机构的）官员，高级职员","ex":{"en":"an environmental health officer","cn":"环境卫生官员"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"军官","en":"In the armed forces, an officer is a person in a position of authority.","ex":{"en":"...a retired British army officer","cn":"退役的英国陆军军官"}},{"pos":"N-COUNT 可数名词","cn":"（机构的）高级职员；（尤指政府机构的）官员，公务员","en":"An officer is a person who has a responsible position in an organization, especially a government organization.","ex":{"en":"...a local authority education officer.","cn":"当地政府的教育官员"}},{"pos":"N-COUNT 可数名词","cn":"警察；警官","en":"Members of the police force can be referred to as officers .","ex":{"en":"...senior officers in the West Midlands police force","cn":"西米德兰兹郡警队的高级警官"}}]},"examples":[{"en":"The matter was passed on to me, as your commanding officer.","cn":"作为你的指挥官，这件事转到了我这里。"},{"en":"Yes, officer, I saw what happened.","cn":"是，警察先生，我看到了发生的事。"}]},"offended":{"oxford":{"phon":"əˈfendɪd","pos":"adjective","senses":[{"en":"feeling upset because of something said or done that is rude or embarrassing","cn":"得罪；冒犯","ex":{"en":"Alice looked rather offended.","cn":"艾丽斯一副受到冒犯而不快的样子。"}}]},"media":{"uk":"media/uk/offended__gb_1.mp3","us":"media/us/offended__us_1.mp3"},"examples":[{"en":"Alice looked rather offended.","cn":"艾丽斯显得愤愤不已。"}],"base":"offend"},"offices":{"lemma":"office"},"officials":{"lemma":"official"},"offers":{"lemma":"offer"},"offsetting":{"lemma":"offset"},"officers":{"lemma":"officer"},"offered":{"lemma":"offer"},"offender":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"犯罪者；违法者；罪犯","en":"An offender is a person who has committed a crime.","ex":{"en":"The authorities often know that sex offenders will attack again when they are released.","cn":"当局一般都知道性犯罪者在获释后往往会再次犯案。"}},{"pos":"N-COUNT 可数名词","cn":"造成问题的人（或事物）","en":"You can refer to someone or something which you think is causing a problem as an offender .","ex":{"en":"The contraceptive pill is the worst offender, but it is not the only drug to deplete the body's vitamin levels.","cn":"避孕药的危害最大，但是它并不是唯一一种消耗体内维生素的药物。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is involved in illegal activities or has been proved guilty of a crime. Criminal is used especially about someone who often does things that are illegal","cn":""},{"en":"someone who breaks the law","cn":""},{"en":"a dishonest person, especially one who steals money and who you cannot trust","cn":""}]},"collocations":{"phrases":["ADJ. alleged | convicted | first As a first offender, he received a lenient sentence. | persistent | adult, juvenile, young | sex","VERB + OFFENDER sentence 2 sb/sth that causes trouble","ADJ. main, worst As regards pollution, old diesel-engined vehicles are the worst offenders."]},"media":{"uk":"media/ldoce/hwd/bre/e/brelasdeoffender.mp3","us":"media/ldoce/hwd/ame/1/offender.mp3"},"examples":[{"en":"When it comes to pollution, the chemical industry is a major offender.","cn":"谈到环境污染问题，化工产业是一大祸害。"},{"en":"a persistent/serious/violent, etc. offender","cn":"惯犯、重犯、暴力犯等"}],"oxford":{"phon":"əˈfendə(r)","pos":"noun","senses":[{"en":"a person who commits a crime","cn":"犯罪者；违法者；罪犯","lab":"rather formal","ex":{"en":"a persistent/serious/violent, etc. offender","cn":"惯犯、重犯、暴力犯等"}},{"en":"a person or thing that does something wrong","cn":"妨害…的人（或事物）","ex":{"en":"The report on sexual discrimination at work shows that some of the worst offenders are women.","cn":"关于工作场所性别歧视的报告显示，一些最严重的犯罪者是女性。"}}]}},"off-putting":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（某物的特性或特定方面）令人讨厌的，惹人不快的，让人避而远之的","en":"If you describe a quality or feature of something as off-putting, you mean that it makes you dislike that thing or not want to get involved with it.","ex":{"en":"However, many customers found the smell of this product distinctly off-putting.","cn":"然而，很多顾客觉得该产品有一股异味，非常难闻。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if someone’s behaviour or the appearance of something is off-putting, you do not like it or you think it is unattractive 〔","cn":"某人的举止或某物的外观〕令人气恼的﹐令人讨厌的"}]},"collocations":{"phrases":["VERBS be | find sth I find it very off-putting when people don't look me in the eye.","ADV. distinctly, very | a bit, a little, rather, slightly The noise was rather off-putting."]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41off-putting.mp3","us":"media/ldoce/hwd/ame/1/ld41off-putting.mp3"},"examples":[{"en":"I find his manner very off-putting.","cn":"我觉得他的举止令人颇为厌恶。"},{"en":"Some women found the competitive style of the discussions off-putting.","cn":"有些女性觉得这种互不相让的讨论方式让人反感。"}],"oxford":{"phon":"ˈɒf pʊtɪŋ","pos":"adjective","senses":[{"en":"not pleasant, in a way that prevents you from liking somebody/something","cn":"令人烦恼的；令人讨厌的","ex":{"en":"I find his manner very off-putting.","cn":"我觉得他的举止令人颇为厌恶。"}}]}},"offside":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（足球、曲棍球等比赛中）越位的","en":"In games such as football or hockey, when an attacking player is offside, they have broken the rules by being nearer to the goal than a defending player when the ball is passed to them.","ex":{"en":"The goal was disallowed because Wark was offside.","cn":"由于沃克越位在先，这个进球被判无效。"}},{"pos":"ADJ 形容词","cn":"（美式橄榄球中）越位的","en":"In American football, a player is offside if they cross the line of scrimmage before a play begins."},{"pos":"N-SING 单数名词","cn":"（车辆在靠左交通中的）右侧，外侧，远离路边的一侧","en":"The offside of a vehicle is the side that is farthest from the edge of the road when the vehicle is being driven normally.","ex":{"en":"The driver of the car lowered his offside front window.","cn":"司机摇下前排右侧的玻璃窗。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"in a position, usually ahead of the ball, where you are not allowed to play the ball in sports such as soccer and hockey 〔","cn":"足球、曲棍球等运动中〕越位(的)"},{"en":"the side of a car that is nearest to the middle of the road when you are driving it 〔","cn":"汽车的〕右侧﹐右边﹔外侧"}]},"collocations":{"phrases":["VERBS be, look | catch sb, rule sb an attempt to catch an opponent offside He was ruled offside by the referee."]},"media":{"uk":"media/ldoce/hwd/bre/e/offside_adj0205.mp3","us":"media/ldoce/hwd/ame/9/l3offside.mp3"},"examples":[{"en":"He was offside when he scored.","cn":"他将球攻进门时已越位了。"},{"en":"The goal was disallowed for offside.","cn":"因为越位，进球无效。"}],"oxford":{"phon":"ˌɒfˈsaɪd","pos":"adjective","senses":[{"en":"in some sports, for example football (soccer) and ice hockey, a player is offside if they are in a position, usually ahead of the ball, that is not allowed","cn":"（足球、曲棍球等体育运动中）越位的","lab":"US English also","ex":{"en":"He was offside when he scored.","cn":"他进球时已越位了。"}},{"en":"on the side of a vehicle that is furthest from the edge of the road","cn":"（车辆）外侧的，右侧的","lab":"British English","ex":{"en":"the offside mirror","cn":"右侧镜"}},{"en":"the fact of being offside in a game such as football (soccer) or ice hockey","cn":"（足球、冰球等体育运动中的）越位","lab":"US English also","ex":{"en":"The goal was disallowed for offside.","cn":"因为越位，进球无效。"},"pos":"noun"},{"en":"the side of a vehicle that is furthest from the edge of the road","cn":"（车辆的）外侧，远侧，右侧","lab":"British English","ex":{"en":"The offside was damaged.","cn":"车辆外侧受损。"},"pos":"noun"},{"en":"in a position, usually ahead of the ball, that is not allowed","cn":"越位","ex":{"en":"He was ruled offside by the referee.","cn":"他被裁判判为越位。"},"pos":"adverb"}]}}});
